"""Ensure the Android reporting code accepts a valid JS-optimizer result."""
import json
import sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'app/src/main/python'))
from excel_export import make_excel
from csv_export_mobile import make_export
# Test real result when generated by Node in the preceding test.
result_path=ROOT/'tests'/'example_js_result.json'
if result_path.exists():
    data=json.loads(result_path.read_text(encoding='utf8'))
    assert make_excel(data,'Người chơi A').startswith(b'PK')
    assert make_export(data,'Người chơi A').startswith(b'PK')
    print('PASS - XLSX and CSV ZIP from actual JS result')
else:
    # In a clean checkout, check export functions are importable and known constants.
    assert callable(make_excel) and callable(make_export)
    print('PASS - Export modules loaded (no SciPy required)')
